def dense_linear_tracking(env, command_name='base_velocity', std=.5):
    command, velocity, _ = motion_state(env, command_name)
    return torch.exp(-(command[:, :2] - velocity).square().sum(-1) / std**2)

def dense_angular_tracking(env, command_name='base_velocity', std=.5):
    command, _, yaw = motion_state(env, command_name)
    return torch.exp(-(command[:, 2] - yaw).square() / std**2)

def lin_vel_z_l2(env: ManagerBasedRLEnv, asset_cfg: SceneEntityCfg = SceneEntityCfg("robot")) -> torch.Tensor:
    """Penalize z-axis base linear velocity using L2 squared kernel."""
    # extract the used quantities (to enable type-hinting)
    asset: RigidObject = env.scene[asset_cfg.name]
    return torch.square(asset.data.root_lin_vel_b.torch[:, 2])

def ang_vel_xy_l2(env: ManagerBasedRLEnv, asset_cfg: SceneEntityCfg = SceneEntityCfg("robot")) -> torch.Tensor:
    """Penalize xy-axis base angular velocity using L2 squared kernel."""
    # extract the used quantities (to enable type-hinting)
    asset: RigidObject = env.scene[asset_cfg.name]
    return torch.sum(torch.square(asset.data.root_ang_vel_b.torch[:, :2]), dim=1)

def action_rate_l2(env: ManagerBasedRLEnv) -> torch.Tensor:
    """Penalize the rate of change of the actions using L2 squared kernel."""
    return torch.sum(torch.square(env.action_manager.action - env.action_manager.prev_action), dim=1)

def is_terminated(env: ManagerBasedRLEnv) -> torch.Tensor:
    """Penalize terminated episodes that don't correspond to episodic timeouts."""
    return env.termination_manager.terminated.float()

def low_pelvis_height(env, target_height=.55, asset_cfg=SceneEntityCfg('robot')):
    """Soft squat cost above the lower ankle; permits terrain-dependent bending."""
    data = env.scene[asset_cfg.name].data
    support_z = tensor(data.body_pos_w)[:, asset_cfg.body_ids, 2].min(dim=1).values
    clearance = tensor(data.root_pos_w)[:, 2] - support_z
    return (target_height - clearance).clamp_min(0.).square()

def is_alive(env: ManagerBasedRLEnv) -> torch.Tensor:
    """Reward for being alive."""
    return (~env.termination_manager.terminated).float()

def descent_overspeed_penalty(env, command_name='base_velocity'):
    c = env.command_manager.get_term(command_name)
    actual = tensor(c.robot.data.root_lin_vel_w)[:, :2].norm(dim=-1)
    desired = c.vel_command_b[:, :2].norm(dim=-1)
    enabled = (c.group == 2) & ~c._skip_progress_transition
    return overspeed_cost(actual, desired, enabled)
